/// `#[repr(C)]` mirrors of the library's copy structs in the Vesper word
/// layout (export ABI v3): `in`/`inout` parameters and slices of them are
/// lent to Vesper in place.
pub mod repr {
    /// Mirror of the Vesper copy struct `Draw` (2 words).
    #[repr(C)]
    #[derive(Clone, Copy, Debug, PartialEq)]
    pub struct Draw {
        pub code: u64,
        pub value: u64,
    }

    /// Mirror of the Vesper copy struct `FuzzStats` (5 words).
    #[repr(C)]
    #[derive(Clone, Copy, Debug, PartialEq)]
    pub struct FuzzStats {
        pub execs: u64,
        pub invalid: u64,
        pub solver_runs: u64,
        pub solver_hits: u64,
        pub features: u64,
    }

    /// Mirror of the Vesper copy struct `Key` (3 words).
    #[repr(C)]
    #[derive(Clone, Copy, Debug, PartialEq)]
    pub struct Key {
        pub len: u64,
        pub hi: u64,
        pub lo: u64,
    }

    /// Mirror of the Vesper copy struct `Rng` (1 words).
    #[repr(C)]
    #[derive(Clone, Copy, Debug, PartialEq)]
    pub struct Rng {
        pub word: u64,
    }

    /// Mirror of the Vesper copy struct `SearchStats` (3 words).
    #[repr(C)]
    #[derive(Clone, Copy, Debug, PartialEq)]
    pub struct SearchStats {
        pub sleep_blocked: u64,
        pub cache_hits: u64,
        pub bound_pruned: u64,
    }

    /// Mirror of the Vesper copy struct `Stats` (5 words).
    #[repr(C)]
    #[derive(Clone, Copy, Debug, PartialEq)]
    pub struct Stats {
        pub runs: u64,
        pub accepted: u64,
        pub invalid: u64,
        pub not_reproducing: u64,
        pub budget_exhausted: vesper_port_abi::Word<bool>,
    }

}

// The mirror of `Draw` has exactly the Vesper layout.
const _: () = {
    assert!(core::mem::size_of::<repr::Draw>() == 2 * 8);
    assert!(core::mem::align_of::<repr::Draw>() == 8);
    assert!(core::mem::offset_of!(repr::Draw, code) == 0 * 8);
    assert!(core::mem::offset_of!(repr::Draw, value) == 1 * 8);
};

// SAFETY: `repr::Draw` is `#[repr(C)]`, 2 words, eight-byte aligned
// (asserted above), and every field is a word cell or a mirror.
unsafe impl vesper_port_abi::Mirror for repr::Draw {
    const WORDS: usize = 2;
}

impl repr::Draw {
    /// The mirror of a Rust value.
    pub fn from_value(value: &Draw) -> Self {
        let mut words = [0u64; 2];
        Abi::put(value, &mut words);
        vesper_port_abi::mirror_from_words(&words)
    }

    /// The Rust value of the mirror.
    pub fn to_value(&self) -> Draw {
        <Draw as Abi>::get(vesper_port_abi::mirror_words(self))
    }
}

